import unittest

import numpy as np

from deepmd.dpmodel.utils.neighbor_graph import GraphLayout, NeighborGraph


class TestNeighborGraphDataclass(unittest.TestCase):
    def test_construct_minimal(self) -> None:
        graph = NeighborGraph(
            n_node=np.array([2], dtype=np.int64),
            edge_index=np.array([[1, 0], [0, 1]], dtype=np.int64),
            edge_vec=np.zeros((2, 3), dtype=np.float64),
            edge_mask=np.array([True, True]),
        )
        self.assertEqual(graph.edge_index.shape, (2, 2))
        self.assertIsNone(graph.n_local)
        self.assertIsNone(graph.angle_index)
        self.assertIsNone(graph.angle_mask)

    def test_graphlayout_defaults(self) -> None:
        layout = GraphLayout()
        self.assertIsNone(layout.edge_capacity)
        self.assertIsNone(layout.angle_capacity)
        self.assertIsNone(layout.node_capacity)
        self.assertIsNone(layout.frame_capacity)
        self.assertEqual(layout.min_edges, 2)

